    assert(asc[0] == 1)
    assert(asc[1] == 2)
    assert(asc[2] == 3)
    assert(asc[3] == 4)

    // Test 2: Sort descending
    let desc = sort4(data, cmp_desc)
    assert(desc[0] == 4)
    assert(desc[1] == 3)
    assert(desc[2] == 2)
    assert(desc[3] == 1)

    // Test 3: Already sorted input
    let sorted: [i64; 4] = [1, 2, 3, 4]
