//@ run-pass
//@ expect-stdout-contains: PASS hessian_correction_reduces_residual
// tests/run-pass/dissertation_pbpk14_hessian.sio
//
// End-to-end demonstration of the second-order GUM Hessian propagator.
// Two halves:
//
//   (1) Synthetic-output residual proof.  For a controlled non-linear
//       endpoint y = a · x², the analytic variance is closed-form.  We
//       compute it three ways: ground truth, GUM 1st order (Jacobian),
//       GUM 2nd order (Jacobian + Hessian correction).  The acceptance
//       check is |GUM_2nd − truth| < |GUM_1st − truth| — the dissertation
//       claim that the 2nd-order term moves the GUM estimate toward the
//       true variance for non-linear outputs.
//
//   (2) Rapamycin AUC Hessian budget.  Runs the propagator on a
//       2-parameter rapamycin sub-case (CL_hep × fu_plasma) and emits a
//       CSV-format budget.  The companion gate redirects this section
//       to benchmarks/pbpk/hessian_budget.csv.
//
// Final stdout line: "PASS hessian_correction_reduces_residual"

use darwin_pbpk::tsit5_pbpk14::*
use darwin_pbpk::epistemic_pbpk14::{EpPrior14, ep14_rapamycin_params}
use darwin_pbpk::epistemic_pbpk14_hessian::*

fn hessian_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var v = x
    var scale = 1.0
    while v < 1.0 {
        v = v * 4.0
        scale = scale * 2.0
    }
    var y = v
    var i = 0
    while i < 20 {
        y = 0.5 * (y + v / y)
        i = i + 1
    }
    y / scale
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool with Mut, Div, Panic {
    var d = a - b
    if d < 0.0 { d = 0.0 - d }
    d < tol
}

fn abs_diff(a: f64, b: f64) -> f64 with Mut, Div, Panic {
    var d = a - b
    if d < 0.0 { d = 0.0 - d }
    d
}

fn fail(tag: string) with IO, Mut, Panic, Div {
    print("FAIL hessian_correction_reduces_residual: ")
    println(tag)
}

// ----------------------------------------------------------------------
// (1) Synthetic non-linear endpoint y = a · x²
// ----------------------------------------------------------------------
//
// For x ~ N(μ, σ²):
//   E[y]      = a (μ² + σ²)
//   Var(y)    = a² · ( 4 μ² σ² + 2 σ⁴ )         (exact)
//
// GUM 1st order:
//   c = ∂y/∂x = 2 a μ
//   Var₁ = c² σ² = 4 a² μ² σ²                    (misses 2 a² σ⁴)
//
// GUM 2nd order:
//   H = ∂²y/∂x² = 2 a
//   correction = ½ · H² · σ⁴ = 2 a² σ⁴
//   Var₂ = Var₁ + correction = 4 a² μ² σ² + 2 a² σ⁴   (exact)
//
// So |Var₁ − truth| = 2 a² σ⁴, |Var₂ − truth| = 0.

fn synthetic_residual_test() -> bool with IO, Mut, Div, Panic {
    let a:    f64 = 0.7
    let mu:   f64 = 1.5
    let sig2: f64 = 0.04            // σ² = 0.04, σ = 0.2

    // Ground truth.
    let var_truth = a * a * (4.0 * mu * mu * sig2 + 2.0 * sig2 * sig2)

    // GUM 1st order (analytic c).
    let c1 = 2.0 * a * mu
    let var_1 = c1 * c1 * sig2

    // GUM 2nd order via 4-point central FD on the synthetic output.
    let h: f64 = 0.01 * hessian_sqrt(sig2)
    let f0  = a * mu * mu
    let fp  = a * (mu + h) * (mu + h)
    let fn1 = a * (mu - h) * (mu - h)
    let c_fd = (fp - fn1) / (2.0 * h)
    let h_fd = (fp - 2.0 * f0 + fn1) / (h * h)
    let var_2 = c_fd * c_fd * sig2 + 0.5 * h_fd * h_fd * sig2 * sig2

    let r1 = abs_diff(var_1, var_truth)
    let r2 = abs_diff(var_2, var_truth)

    print("synthetic var_truth="); print_f64(var_truth)
    print(" var_o1=");             print_f64(var_1)
    print(" var_o2=");              print_f64(var_2)
    print(" r1=");                  print_f64(r1)
    print(" r2=");                  print_f64(r2)
    println("")

    r2 < r1
}

// ----------------------------------------------------------------------
// (2) Rapamycin AUC Hessian budget — emit CSV-format rows.
//
// Use a 2-parameter sub-case (CL_hep, fu_plasma) to limit the
// simulation count.  ~9 PBPK simulations total (1 ref + 4 Jacobian +
// 4 off-diagonal corner + 0 extra diagonal — 3-point diagonal reuses
// the Jacobian's perturbed AUC values).
// ----------------------------------------------------------------------

fn rapamycin_priors_2param() -> EpPrior14 with Mut, Div, Panic {
    var p = EpPrior14 {
        mean:       [0.0; 8],
        variance:   [0.0; 8],
        confidence: [0.0; 8],
        n: 0,
    }
    p.n = 2
    // 0: cl_hepatic (CYP3A4, CV~60%)
    p.mean[0]       = 12.4
    p.variance[0]   = 6.0       // smaller σ to keep sims well-conditioned
    p.confidence[0] = 0.65
    // 1: fu_plasma (Schreiber 1991)
    p.mean[1]       = 0.08
    p.variance[1]   = 0.0001
    p.confidence[1] = 0.55
    p
}

fn emit_rapamycin_budget() with IO, Mut, Panic, Div {
    let prm    = ep14_rapamycin_params()
    let priors = rapamycin_priors_2param()
    let dose   = 6.0
    let t_end  = 1.0       // 1 h window — short enough that Euler is stable

    let bud = hessian_pbpk14_auc(prm, priors, dose, t_end)

    // Full-precision channel for the first-order variance (pbpk28-parity
    // gate pattern: raw values out of Sounio, CSV shaping in the gate).
    // print_f64 emits six fixed decimals, which floors var_first_order
    // (~2e-7 (ng·h/mL)²) to 0.000000 in the budget row below — a bytewise
    // reader cannot witness the value from that row. The companion gate
    // reads this scaled line and canonicalises it back to %.6e.
    print("HESSBUD|var_o1_scaled_1e9=")
    print_f64(bud.var_first_order * 1000000000.0)
    println("")

    println("# rapamycin_hessian_budget_v1")
    hessian_emit_csv_header()
    hessian_emit_budget_csv(bud)
}

fn main() with IO, Mut, Panic, Div {
    // (1) synthetic non-linear residual proof
    let ok = synthetic_residual_test()
    if !ok {
        fail("synthetic_test_did_not_reduce_residual")
        return
    }

    // (2) rapamycin Hessian CSV emission (smoke — checked by the gate
    // for the bytestable header line, not for numerical match)
    emit_rapamycin_budget()

    println("PASS hessian_correction_reduces_residual")
}

//@ run-pass
//@ description: PBPK28 rapamycin priors carried as Knowledge<f64> with literature ε.
//@ A dosing summary declared at the HONEST evidence ceiling (with Epistemic(400),
//@ the weakest prior) compiles and runs. The over-claim counterpart
//@ (with Epistemic(950)) is rejected — see compile-fail/dissertation_pbpk28_overclaim.sio.
//@ METHOD demonstration of compile-time confidence gates (dissertation Contribution 2);
//@ NOT a clinical dosing engine — ε is literature evidence-quality, not a probability.
//
// These are the real rapamycin priors from stdlib/darwin_pbpk/epistemic_pbpk28.sio
// (ep28_rapamycin_priors), where confidence was a plain f64 the type system could
// not see. Carried as Knowledge<f64, ε> they become first-class: the ε flows into
// the EpistemicComplete gate, so a function cannot claim more confidence than its
// weakest input supports.
//
//   cl_hepatic ε=0.65 (Jiao/Zhang 2009 pop-PK, CV≈38%)
//   fu_plasma  ε=0.72 (Schreiber 1991, CV≈25%)
//   kp_liver   ε=0.60 (Valoteau 1996, CV≈25%)
//   kp_adipose ε=0.40 (capped model, CV≈40%)   ← the weakest evidence
//
// Gate semantics (per-token, NOT combined): `with Epistemic(N)` requires EVERY
// input expression to individually carry confidence ≥ N. It does NOT certify the
// propagated/combined confidence of the result (that compounds far lower). So the
// maximum satisfiable N is the WEAKEST single prior, kp_adipose ε=0.40 → 400:
// verified that Epistemic(400) compiles but Epistemic(401) already rejects (and
// Epistemic(650) flags both kp_adipose and kp_liver). This is the type system
// refusing to let any under-evidenced input enter a high-confidence claim.

fn rapa_dosing_summary() -> f64 with Epistemic(400), Mut, Div, Panic {
    let cl_hepatic: Knowledge[f64] = Knowledge(12.4, ε=0.65, prov="Jiao2009_popPK_CV38");
    let fu_plasma:  Knowledge[f64] = Knowledge(0.08, ε=0.72, prov="Schreiber1991_CV25");
    let kp_liver:   Knowledge[f64] = Knowledge(5.40, ε=0.60, prov="Valoteau1996_CV25");
    let kp_adipose: Knowledge[f64] = Knowledge(0.30, ε=0.40, prov="capped_model_CV40");
    cl_hepatic.value + fu_plasma.value + kp_liver.value + kp_adipose.value
}

fn main() with IO, Mut, Div, Panic, Epistemic {
    // Σ of the four prior central values (12.4 + 0.08 + 5.40 + 0.30 = 18.18),
    // proving the gated body actually compiled and executed.
    println(rapa_dosing_summary());
    println("PBPK28_CONFIDENCE_GATE_PASS");
}

//@ run-pass
//@ timeout: 90
// ============================================================================
// DISSERTATION PBPK28 PARITY REFERENCE — DEGENERATE (V_v→0, PS→∞)
//
// Companion to website/src/lib/pbpk28_core.mjs and the parity gate at
// scripts/ci/dissertation_pbpk28_parity_gate.sh (Case 2: asymptotic reduction
// of PBPK28 → PBPK14 well-stirred).
//
// Degenerate configuration:
//   vasc_frac_at(i) = 1e-3 ∀ organs (vs 0.019–0.282 in the literature ref)
//   ps_at(i)        = lit_PS_i × 1e4   (drives PS-coupling instantaneous)
// At these parameters CN's A-stability is essential — explicit RK4 in the
// slow operator would require dt ~ 1e-7 h for kidney/lung; CN integrates
// stably at dt = 0.001 h.
//
// CORRECTED asymptotic claim (G-α-β math correction):
//   PBPK28 at (V_v → 0, PS → ∞) does NOT reduce to PBPK14 well-stirred. It
//   reduces to a *1-state quasi-steady-state (QSS) model*:
//     V_eff · dC_b/dt = -cl_hep · C_b + release,
//     V_eff = V_b + Σ V_i · Kp_i
//     C_v_i = C_b instantly; C_t_i = Kp_i · C_b instantly.
//
//   PBPK14 well-stirred sits BETWEEN PBPK28-lit (finite PS, finite V_v) and
//   PBPK28-degenerate (V_v→0, PS→∞). The three models form a hierarchy in
//   model-form complexity; PBPK14 is the *intermediate* approximation where
//   tissue redistributes instantly *within* an organ but blood-to-tissue
//   transport remains rate-limited by Q. PBPK28-degenerate additionally
//   assumes blood-to-tissue transport is also instantaneous.
//
// This file remains useful as: (a) the target trajectory for the
// fully-coupled CN A-stability proof at extreme stiffness, and (b) the
// numerical demonstration that PBPK28-degenerate matches the 1-state QSS
// limit (asymptotic verification of the model-reduction theorem).
// Quantitative match against the 1-state QSS limit at literature
// parameters provides the Type B model-form uncertainty contribution per
// JCGM 100:2008 §4.3 (the G-α-γ follow-up will emit benchmarks/pbpk/
// model_form_uc.csv from these comparisons).
//
// Model: permeability-limited PBPK, 14 organs × {vascular, interstitial}.
//   V_v,i · dC_v,i/dt = Q_i·(C_blood - C_v,i) - PS_i·(C_v,i - C_t,i/Kp_i)
//   V_t,i · dC_t,i/dt = PS_i·(C_v,i - C_t,i/Kp_i)
//   V_b   · dC_b/dt   = sum_i Q_i·(C_v,i - C_b) - cl_hep·C_b
//
// Integrator: fully-coupled Crank-Nicolson on the 27-state PBPK28 system —
// no operator splitting. PS coupling and Q transport integrated implicitly in
// one CN step via per-organ Schur-complement elimination + scalar reduction
// for C_blood. A-stable, 2nd-order, no splitting-induced bias.
//
// Compartment indexing matches website/src/components/dissertation/compartments.ts:
//   0=blood 1=liver 2=kidney 3=brain 4=heart 5=lung 6=muscle 7=adipose
//   8=gut   9=skin  10=bone   11=spleen 12=pancreas 13=other
//
// Bolus 0.05 mg into blood (C_blood(0) = 0.01 mg/L). cl_hep = 12.4 L/h. Stent off.
// Twelve log-spaced sample times. Emits PARITY|t / PARITY|i / PARITY|cv / PARITY|ct
// / PARITY|cavg records — the gate joins on (t, i) and compares against the
// Node runner's identical output.
// ============================================================================

struct Pbpk28 { cv: [f64; 14], ct: [f64; 14] }

fn pbpk28_zero() -> Pbpk28 { Pbpk28 { cv: [0.0; 14], ct: [0.0; 14] } }

// V_i, L, ICRP standard man 70 kg (matches pbpk14_core.mjs V_REF).
fn vref_at(i: i64) -> f64 {
    if i ==  0 { return 5.0 }
    if i ==  1 { return 1.8 }
    if i ==  2 { return 0.31 }
    if i ==  3 { return 1.45 }
    if i ==  4 { return 0.33 }
    if i ==  5 { return 1.1 }
    if i ==  6 { return 28.0 }
    if i ==  7 { return 20.0 }
    if i ==  8 { return 1.2 }
    if i ==  9 { return 3.6 }
    if i == 10 { return 6.6 }
    if i == 11 { return 0.18 }
    if i == 12 { return 0.09 }
    return 3.7
}

// DEGENERATE vasc_frac: 1e-3 for all organs (was 0.019–0.282).
// Drives the V_v→0 limit; CN A-stability handles the resulting Q/V_v
// eigenvalue blow-up (~O(7e4) for kidney) unconditionally.
fn vasc_frac_at(i: i64) -> f64 {
    if i == 0 { return 1.000 }
    return 0.001
}

// Kp (rapamycin partition coefficient, tissue:vascular at equilibrium).
fn kp_at(i: i64) -> f64 {
    if i ==  0 { return 1.00 }
    if i ==  1 { return 5.40 }
