// ---- Math helpers ----

fn ep_abs(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn ep_sqrt(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 {
        y = (y + x / y) * 0.5
        i = i + 1
    }
    return y
}

fn ep_max(a: f64, b: f64) -> f64 {
    if a > b { return a }
    return b
}

// Print f64 as "integer.fraction" using multiply-truncate (6 digits)
fn print_f64_6(v: f64) -> i64 with IO {
    if v < 0.0 {
        print("-")
        let neg_v = 0.0 - v
        let int_part = neg_v as i64
        let frac = ((neg_v - (int_part as f64)) * 1000000.0) as i64
        print_int(int_part)
        print(".")
        // Pad with leading zeros
        if frac < 100000 { print("0") }
        if frac < 10000 { print("0") }
        if frac < 1000 { print("0") }
        if frac < 100 { print("0") }
        if frac < 10 { print("0") }
        print_int(frac)
        return 0
    }
    let int_part = v as i64
    let frac = ((v - (int_part as f64)) * 1000000.0) as i64
    print_int(int_part)
    print(".")
    if frac < 100000 { print("0") }
    if frac < 10000 { print("0") }
    if frac < 1000 { print("0") }
    if frac < 100 { print("0") }
    if frac < 10 { print("0") }
    print_int(frac)
    return 0
}

