        while i < n {
            if a[i as usize] > threshold {
                result[i as usize] = 1
            } else {
                result[i as usize] = 0
            }
            i = i + 1
        }
    } else {
        // CPU fallback
        var i: i64 = 0
        while i < n {
            if a[i as usize] > threshold {
                result[i as usize] = 1
            } else {
                result[i as usize] = 0
            }
            i = i + 1
        }
    }

    result
}

