// Test 10: Solve SPD system via Cholesky
fn test_cholesky_solve() -> bool with Mut, Panic, Div {
    // SPD: A = [[4, 2, 0], [2, 5, 1], [0, 1, 3]]
    let A = make_3x3(
        4.0, 2.0, 0.0,
        2.0, 5.0, 1.0,
        0.0, 1.0, 3.0
    )
    let n = 3
    var b = zeros8()
    b[0] = 6.0
    b[1] = 8.0
    b[2] = 4.0

    let ch = cholesky_factorize(A, n)

    var y = zeros8()
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + mat_get(ch.L, n, i, j) * y[j]
            j = j + 1
        }
        y[i] = (b[i] - sum) / mat_get(ch.L, n, i, i)
        i = i + 1
    }

    var x = zeros8()
    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + mat_get(ch.L, n, j, i) * x[j]
            j = j + 1
        }
        x[i] = (y[i] - sum) / mat_get(ch.L, n, i, i)
        i = i - 1
    }

    var err = 0.0
    i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < n {
            sum = sum + mat_get(A, n, i, j) * x[j]
            j = j + 1
        }
        let diff = sum - b[i]
        err = err + diff * diff
        i = i + 1
    }
    err = sqrt_f64(err)

    return err < 1e-10
}

