//@ run-pass
// LSP cross-file navigation — module resolver symbol index
//
// Verifies the LspgSymBridge pattern introduced in lsp/goto_def.sio Section 27:
// bridge table maps resolver symbol_id → def_id so the module-graph hierarchical
// lookup replaces the legacy flat scan for cross-file goto-definition.
//
// This test is self-contained — it simulates the bridge table logic inline
// without importing compiler internals.

// Minimal bridge table: symbol_id → def_id
struct SymBridge { sym_id: i64, def_id: i64, file_id: i64, line: i64 }

fn bridge_find(table: &[SymBridge; 8], count: i64, sym_id: i64) -> i64 with Panic, Mut {
    var i: i64 = 0
    while i < count {
        if table[i as usize].sym_id == sym_id { return table[i as usize].def_id }
        i = i + 1
    }
    return 0 - 1
}

fn bridge_location(table: &[SymBridge; 8], count: i64, sym_id: i64) -> i64 with Panic, Mut {
    var i: i64 = 0
    while i < count {
        if table[i as usize].sym_id == sym_id { return table[i as usize].line }
        i = i + 1
    }
    return 0 - 1
}

// Simulate mod_graph_resolve_import: qualified "mod::sym" lookup
// Returns symbol_id on hit, -1 on miss
fn resolve_qualified(name_mod: i64, name_sym: i64) -> i64 with Panic {
    // Registry: mod=1,sym=10 → symbol_id=100 (file A, line 5)
    //           mod=1,sym=20 → symbol_id=101 (file A, line 12)
    //           mod=2,sym=30 → symbol_id=200 (file B, line 7)
    if name_mod == 1 && name_sym == 10 { return 100 }
    if name_mod == 1 && name_sym == 20 { return 101 }
    if name_mod == 2 && name_sym == 30 { return 200 }
    return 0 - 1
}

fn main() -> i32 with IO, Mut, Panic {
    var passed: i32 = 0
    var failed: i32 = 0

    // Build bridge table (3 registered symbols)
    var tbl: [SymBridge; 8] = [SymBridge { sym_id: 0, def_id: 0, file_id: 0, line: 0 }; 8]
    tbl[0] = SymBridge { sym_id: 100, def_id: 1, file_id: 1, line: 5  }
    tbl[1] = SymBridge { sym_id: 101, def_id: 2, file_id: 1, line: 12 }
    tbl[2] = SymBridge { sym_id: 200, def_id: 3, file_id: 2, line: 7  }
    let count: i64 = 3

    // T1: bridge lookup hit
    let d1 = bridge_find(&tbl, count, 100)
    if d1 == 1 { passed = passed + 1 }
    else { println("T1 FAIL"); failed = failed + 1 }

    // T2: bridge lookup miss returns -1
    let d_miss = bridge_find(&tbl, count, 999)
    if d_miss == 0 - 1 { passed = passed + 1 }
    else { println("T2 FAIL"); failed = failed + 1 }

    // T3: qualified resolve → bridge → line number
    let sym3 = resolve_qualified(1, 10)
    let line3 = bridge_location(&tbl, count, sym3)
    if sym3 == 100 && line3 == 5 { passed = passed + 1 }
    else { println("T3 FAIL"); failed = failed + 1 }

    // T4: second qualified resolve → different symbol, line 12
    let sym4 = resolve_qualified(1, 20)
    let line4 = bridge_location(&tbl, count, sym4)
    if sym4 == 101 && line4 == 12 { passed = passed + 1 }
    else { println("T4 FAIL"); failed = failed + 1 }

    // T5: cross-module resolve (mod=2) → def_id=3
    let sym5 = resolve_qualified(2, 30)
    let d5 = bridge_find(&tbl, count, sym5)
    if sym5 == 200 && d5 == 3 { passed = passed + 1 }
    else { println("T5 FAIL"); failed = failed + 1 }

    // T6: graph miss (unknown module) → sym=-1
    let sym_miss = resolve_qualified(99, 99)
    if sym_miss == 0 - 1 { passed = passed + 1 }
    else { println("T6 FAIL"); failed = failed + 1 }

    if failed == 0 { println("lsp_cross_file_nav: PASS") }
    else { println("lsp_cross_file_nav: FAIL") }
    failed as i32
}

//@ run-pass
// Verifies lsp_hover_qualified: bridge table lookup for qualified names
//
// Simulates the module resolver bridge inline (no imports from compiler
// internals).  Tests that a bridge lookup for a qualified name (mod_hash +
// sym_hash → def_id) produces the correct def_id, and that the hover
// placeholder string is formatted as "(qualified symbol, def_id=N)".

// ---- Minimal bridge table ----

struct QBridgeEntry {
    mod_hash: i64,
    sym_hash: i64,
    def_id:   i64,
}

fn qbridge_lookup(
    table: &[QBridgeEntry; 8],
    count: i64,
    mod_hash: i64,
    sym_hash: i64
) -> i64 with Panic, Mut {
    var i: i64 = 0
    while i < count {
        let e = table[i as usize]
        if e.mod_hash == mod_hash && e.sym_hash == sym_hash {
            return e.def_id
        }
        i = i + 1
    }
    return 0 - 1
}

// ---- Minimal hover result buffer ----

struct HoverBuf {
    buf: [i8; 128],
    len: i64,
}

fn hover_buf_new() -> HoverBuf {
    HoverBuf { buf: [0; 128], len: 0 }
}

fn hover_buf_append(buf: &! HoverBuf, b: i8) with Mut, Panic {
    if buf.len < 128 {
        buf.buf[buf.len as usize] = b
        buf.len = buf.len + 1
    }
}

fn hover_buf_append_i64(buf: &! HoverBuf, val: i64) with Mut, Div, Panic {
    if val == 0 {
        hover_buf_append(buf, 48)
        return
    }
    var n = val
    if n < 0 {
        hover_buf_append(buf, 45)
        n = 0 - n
    }
    var digits: [i8; 24] = [0; 24]
    var dlen: i64 = 0
    while n > 0 {
        digits[dlen as usize] = (48 + (n % 10)) as i8
        n = n / 10
        dlen = dlen + 1
    }
    var i = dlen - 1
    while i >= 0 {
        hover_buf_append(buf, digits[i as usize])
        i = i - 1
    }
}

// hover_qualified: simulate lsp_hover_qualified behaviour.
// Returns 1 if def_id >= 0 (hover was filled), 0 otherwise.
fn hover_qualified(result: &! HoverBuf, def_id: i64) -> i64 with Mut, Div, Panic {
    if def_id < 0 {
        return 0
    }
    result.len = 0
    // "(qualified symbol, def_id="
    hover_buf_append(result, 40)   // (
    hover_buf_append(result, 113)  // q
    hover_buf_append(result, 117)  // u
    hover_buf_append(result, 97)   // a
    hover_buf_append(result, 108)  // l
    hover_buf_append(result, 105)  // i
    hover_buf_append(result, 102)  // f
    hover_buf_append(result, 105)  // i
    hover_buf_append(result, 101)  // e
    hover_buf_append(result, 100)  // d
    hover_buf_append(result, 32)   // space
    hover_buf_append(result, 115)  // s
    hover_buf_append(result, 121)  // y
    hover_buf_append(result, 109)  // m
    hover_buf_append(result, 98)   // b
    hover_buf_append(result, 111)  // o
    hover_buf_append(result, 108)  // l
    hover_buf_append(result, 44)   // ,
    hover_buf_append(result, 32)   // space
    hover_buf_append(result, 100)  // d
    hover_buf_append(result, 101)  // e
    hover_buf_append(result, 102)  // f
    hover_buf_append(result, 95)   // _
    hover_buf_append(result, 105)  // i
    hover_buf_append(result, 100)  // d
    hover_buf_append(result, 61)   // =
    hover_buf_append_i64(result, def_id)
    hover_buf_append(result, 41)   // )
    1
}

fn main() -> i32 with IO, Mut, Div, Panic {
    var passed: i32 = 0
    var failed: i32 = 0

    // Build bridge: mod=10,sym=100→def=1  mod=10,sym=200→def=2
    //               mod=20,sym=300→def=3  mod=20,sym=400→def=4
    var tbl: [QBridgeEntry; 8] = [QBridgeEntry { mod_hash: 0, sym_hash: 0, def_id: 0 }; 8]
    tbl[0] = QBridgeEntry { mod_hash: 10, sym_hash: 100, def_id: 1 }
    tbl[1] = QBridgeEntry { mod_hash: 10, sym_hash: 200, def_id: 2 }
    tbl[2] = QBridgeEntry { mod_hash: 20, sym_hash: 300, def_id: 3 }
    tbl[3] = QBridgeEntry { mod_hash: 20, sym_hash: 400, def_id: 4 }
    let count: i64 = 4

    var result: HoverBuf = hover_buf_new()

    // T1: known mod+sym → correct def_id, hover returns 1
    let d1 = qbridge_lookup(&tbl, count, 10, 100)
    let ok1 = hover_qualified(&! result, d1)
    if d1 == 1 && ok1 == 1 && result.len > 0 {
        passed = passed + 1
    } else {
        println("T1 FAIL")
        failed = failed + 1
    }

    // T2: second symbol in same module → def_id=2
    let d2 = qbridge_lookup(&tbl, count, 10, 200)
    let ok2 = hover_qualified(&! result, d2)
    if d2 == 2 && ok2 == 1 {
        passed = passed + 1
    } else {
        println("T2 FAIL")
        failed = failed + 1
    }

    // T3: cross-module symbol → def_id=3
    let d3 = qbridge_lookup(&tbl, count, 20, 300)
    let ok3 = hover_qualified(&! result, d3)
    if d3 == 3 && ok3 == 1 {
        passed = passed + 1
    } else {
        println("T3 FAIL")
        failed = failed + 1
    }

    // T4: miss (unknown mod+sym) → def_id=-1, hover returns 0, buf not touched
    result.len = 0
    let d4 = qbridge_lookup(&tbl, count, 99, 999)
    let ok4 = hover_qualified(&! result, d4)
    if d4 == 0 - 1 && ok4 == 0 && result.len == 0 {
        passed = passed + 1
    } else {
        println("T4 FAIL")
        failed = failed + 1
    }

    // T5: hover buffer starts with '(' when def_id is valid
    let d5 = qbridge_lookup(&tbl, count, 20, 400)
    let ok5 = hover_qualified(&! result, d5)
    let first_byte = result.buf[0]
    if d5 == 4 && ok5 == 1 && first_byte == 40 {
        passed = passed + 1
    } else {
        println("T5 FAIL")
        failed = failed + 1
    }

    // T6: hover buffer ends with ')' and contains def_id digits
    let d6 = qbridge_lookup(&tbl, count, 10, 100)
    let ok6 = hover_qualified(&! result, d6)
    let last_byte = result.buf[(result.len - 1) as usize]
    if d6 == 1 && ok6 == 1 && last_byte == 41 {
        passed = passed + 1
    } else {
        println("T6 FAIL")
        failed = failed + 1
    }

    if failed == 0 { println("lsp_hover_qualified: PASS") }
    else { println("lsp_hover_qualified: FAIL") }
    failed as i32
}

//@ run-pass
//@ expect-stdout-contains: PASS
//
// Native-stage mirror for the M5 held-out replication smoke. The import-heavy
// version remains parked under tests/madaros/ocssm_imported/.

struct Trajectory {
    len: i64,
    speakers: [i64; 256],
    hashes: [i64; 256],
}

fn traj_empty() -> Trajectory {
    // One literal per field: handing the same array local to two fields makes
    // them one array under Madaros (#2152), so every speaker write landed in
    // hashes and both read back as the hash.
    return Trajectory { len: 0, speakers: [0; 256], hashes: [0; 256] }
}

fn traj_push(t: &Trajectory, speaker: i64, hash: i64) -> i64 with Mut {
    let i: i64 = t.len
    if i >= 256 { return i }
    t.speakers[i as usize] = speaker
    t.hashes[i as usize] = hash
    t.len = i + 1
    return t.len
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn mate(hash: i64) -> i64 {
    if hash == 7 { return 871 }
    if hash == 871 { return 7 }
    if hash == 16 { return 712 }
    if hash == 712 { return 16 }
    if hash == 54 { return 918 }
    if hash == 918 { return 54 }
    if hash == 63 { return 927 }
    if hash == 927 { return 63 }
    if hash == 107 { return 971 }
    if hash == 971 { return 107 }
    if hash == 108 { return 972 }
    if hash == 972 { return 108 }
    if hash == 128 { return 384 }
    if hash == 384 { return 128 }
    if hash == 132 { return 542 }
    if hash == 542 { return 132 }
    if hash == 139 { return 1003 }
    if hash == 1003 { return 139 }
    if hash == 190 { return 313 }
    if hash == 313 { return 190 }
    if hash == 250 { return 505 }
    if hash == 505 { return 250 }
    if hash == 489 { return 899 }
    if hash == 899 { return 489 }
    if hash == 547 { return 879 }
    if hash == 879 { return 547 }
    if hash == 574 { return 814 }
    if hash == 814 { return 574 }
    if hash == 599 { return 969 }
    if hash == 969 { return 599 }
    return -1
}

fn embed_axis(hash: i64) -> i64 {
    let r: i64 = hash - (hash / 7) * 7
    return 1 + r
}

fn embed_into(hash: i64, out: &![f64; 8]) with Mut {
    var i: i64 = 0
    while i < 8 {
        out[i as usize] = 0.0
        i = i + 1
    }
    let m: i64 = mate(hash)
    let canonical: i64 = if m >= 0 && hash > m { m } else { hash }
    let axis: i64 = embed_axis(canonical)
    let aux: i64 = if axis == 7 { 1 } else { axis + 1 }
    out[0] = 0.6
    if m >= 0 && hash > m {
        out[axis as usize] = 0.0 - 0.7745966692414834
        out[aux as usize] = 0.2
    } else {
        out[axis as usize] = 0.8
    }
}

fn conj(v: &[f64; 8], out: &![f64; 8]) with Mut {
    out[0] = v[0]
    var i: i64 = 1
    while i < 8 {
        out[i as usize] = 0.0 - v[i as usize]
        i = i + 1
    }
}

fn dist_sq(a: &[f64; 8], b: &[f64; 8]) -> f64 with Mut {
    var s: f64 = 0.0
    var i: i64 = 0
    while i < 8 {
        let d: f64 = a[i as usize] - b[i as usize]
        s = s + d * d
        i = i + 1
    }
    return s
}

fn pair_residual_sq(hash_a: i64, hash_b: i64) -> f64 with Mut {
    var ea: [f64; 8] = [0.0; 8]
    var eb: [f64; 8] = [0.0; 8]
    var ca: [f64; 8] = [0.0; 8]
    embed_into(hash_a, &!ea)
    embed_into(hash_b, &!eb)
    conj(&ea, &!ca)
    return dist_sq(&eb, &ca)
}

fn load_binary(t: &Trajectory, path: string) -> i64 with IO, Mut, Panic {
    let raw: string = read_file(path)
    let sz: i64 = file_size(path)
    if sz < 16 { return 0 }
    let version: i64 = read_i64(raw, 0)
    if version != 1 { return 0 }
    let n: i64 = read_i64(raw, 1)
    if n < 2 { return 0 }
    if sz < 16 + n * 40 { return 0 }
    var idx: i64 = 2
    var i: i64 = 0
    while i < n {
        let speaker: i64 = read_i64(raw, idx)
        let hash_val: i64 = read_i64(raw, idx + 1)
        let _len: i64 = traj_push(t, speaker, hash_val)
        idx = idx + 5
        i = i + 1
    }
    return n
}

fn paired_dist_sq_fold(t: &Trajectory, fold: i64) -> f64 with Mut, Div, Panic {
    if t.len < 2 { return 0.0 }
    var sum: f64 = 0.0
    var count: i64 = 0
    var i: i64 = 0
    var p: i64 = 0
    while i < t.len - 1 {
        if t.speakers[i as usize] != t.speakers[(i + 1) as usize] {
            let mod5: i64 = p - (p / 5) * 5
            var include: i64 = 0
            if fold == 0 { include = 1 }
            if fold == 1 && mod5 != 0 { include = 1 }
            if fold == 2 && mod5 == 0 { include = 1 }
            if include == 1 {
                sum = sum + pair_residual_sq(t.hashes[i as usize], t.hashes[(i + 1) as usize])
                count = count + 1
            }
            p = p + 1
        }
        i = i + 2
    }
    if count == 0 { return 0.0 }
    return sum / (count as f64)
}

fn random_dist_sq_fold(t: &Trajectory, fold: i64) -> f64 with Mut, Div, Panic {
    if t.len < 2 { return 0.0 }
    var sum: f64 = 0.0
    var count: i64 = 0
    var k: i64 = 0
    while k < t.len {
        let mod5: i64 = (k / 2) - ((k / 2) / 5) * 5
        var include: i64 = 0
        if fold == 0 { include = 1 }
        if fold == 1 && mod5 != 0 { include = 1 }
        if fold == 2 && mod5 == 0 { include = 1 }
        if include == 1 {
            let j: i64 = (k + 3) - ((k + 3) / t.len) * t.len
            if j != k {
                sum = sum + pair_residual_sq(t.hashes[k as usize], t.hashes[j as usize])
                count = count + 1
            }
        }
        k = k + 1
    }
    if count == 0 { return 0.0 }
    return sum / (count as f64)
}

fn main() -> i64 with IO, Mut, Div, Panic {
    var t: Trajectory = traj_empty()
    let loaded: i64 = load_binary(&t, "tests/fixtures/f2_swda.bin")
    if loaded < 2 {
        print("FAIL\n")
        return 1
    }

    let dp_train: f64 = paired_dist_sq_fold(&t, 1)
    let dr_train: f64 = random_dist_sq_fold(&t, 1)
    var ratio_train: f64 = 0.0
    if dp_train > 0.0 { ratio_train = dr_train / dp_train }

    let dp_held: f64 = paired_dist_sq_fold(&t, 2)
    let dr_held: f64 = random_dist_sq_fold(&t, 2)
    var ratio_held: f64 = 0.0
    if dp_held > 0.0 { ratio_held = dr_held / dp_held }

    let drift: f64 = abs_f64(dp_held - dp_train)
    let tolerance: f64 = 0.5 * dp_train

    var ok: i64 = 1
    if dp_train <= 0.0 { ok = 0 }
    if dp_train > 0.10 { ok = 0 }
    if ratio_train < 5.0 { ok = 0 }
    if dp_held <= 0.0 { ok = 0 }
    if dp_held > 0.10 { ok = 0 }
    if ratio_held < 5.0 { ok = 0 }
    if drift > tolerance { ok = 0 }

    if ok == 1 { print("PASS\n") } else { print("FAIL\n") }
    return 0
}

