fn oct_norm_sq(o: Octonion) -> f32 {
    o.a * o.a + o.b * o.b + o.c * o.c + o.d * o.d +
    o.e * o.e + o.f * o.f + o.g * o.g + o.h * o.h
}

// Computes the Euclidean norm
fn oct_norm(o: Octonion) -> f32 {
    oct_norm_sq(o).sqrt()
}

// Normalizes an octonion to unit length
fn oct_normalize(o: Octonion) -> Octonion with Panic {
    let n = oct_norm(o)
    if n == 0.0 {
