//@ run-pass
// Cross-validation: Sounio Euler vs analytical Bateman equation
//
// Validates numerical accuracy of the 2-compartment PBPK solver against
// the closed-form Bateman solution at multiple time points.
//
// Analytical solution (Bateman equation):
//   Gut(t)     = Dose * exp(-ka * t)
//   Central(t) = Dose * ka / (ka - ke) * (exp(-ke * t) - exp(-ka * t))
//
// Reference: Gibaldi & Perrier, "Pharmacokinetics", 2nd Ed., Ch. 2

// Approximate exp(x) using Taylor series with range reduction
// For negative x, compute exp(|x|) and invert to avoid catastrophic cancellation
fn exp_pos(x: f64) -> f64 with Mut {
    // Taylor series for positive x converges well
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 40 {
        let nf = n as f64
        term = term * x / nf
        sum = sum + term
        n = n + 1
    }
    sum
}

fn exp_approx(x: f64) -> f64 with Mut {
    if x < -30.0 {
        return 0.0
    }
    if x < 0.0 {
        // exp(-a) = 1/exp(a) — avoids alternating-sign cancellation
        return 1.0 / exp_pos(-x)
    }
    exp_pos(x)
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return -x }
    x
}

struct PBPKState {
    t: f64,
    gut: f64,
    central: f64
}

fn euler_step(s: PBPKState, dt: f64) -> PBPKState {
    let ka = 1.0
    let ke = 0.1
    PBPKState {
        t: s.t + dt,
        gut: s.gut + (-ka * s.gut) * dt,
        central: s.central + (ka * s.gut - ke * s.central) * dt
    }
}

fn main() -> i32 with IO, Div, Mut, Panic {
    let dose = 500.0
    let ka = 1.0
    let ke = 0.1
    let dt = 0.01   // Small dt for accuracy
    let total_steps = 2400   // 24 hours

    // Run simulation
    var s = PBPKState { t: 0.0, gut: dose, central: 0.0 }
    var i = 0
    while i < total_steps {
        s = euler_step(s, dt)
        i = i + 1
    }

    // Analytical solution at t=24h
    let t = 24.0
    let gut_analytical = dose * exp_approx(-ka * t)
    let coeff = dose * ka / (ka - ke)
    let central_analytical = coeff * (exp_approx(-ke * t) - exp_approx(-ka * t))

    // Print comparison
    println(s.gut)
    println(gut_analytical)
    println(s.central)
    println(central_analytical)

    // Validate relative errors
    // Euler is O(dt) global error; with dt=0.01 expect ~1-5% error
    let gut_error = abs_f64(s.gut - gut_analytical)
    let central_error = abs_f64(s.central - central_analytical)

    // Gut: both should be ~0, absolute check
    if gut_error > 0.01 { return 1 }

    // Central: relative error < 5% (Euler first-order accumulation)
    if central_analytical > 1.0 {
        let rel_error = central_error / central_analytical
        if rel_error > 0.05 { return 2 }
    }

    // Check at intermediate time points via checkpoints
    // Re-run and verify at t=2h (near Tmax), t=6h, t=12h
    var s2 = PBPKState { t: 0.0, gut: dose, central: 0.0 }
    var j = 0
    while j < 200 {
        s2 = euler_step(s2, dt)
        j = j + 1
    }
    // t=2h: near Cmax, analytical Central ≈ 379.7
    let c2_analytical = coeff * (exp_approx(-ke * 2.0) - exp_approx(-ka * 2.0))
    if c2_analytical > 1.0 {
        let c2_rel = abs_f64(s2.central - c2_analytical) / c2_analytical
        if c2_rel > 0.05 { return 3 }
    }

    // Continue to t=6h
    while j < 600 {
        s2 = euler_step(s2, dt)
        j = j + 1
    }
    let c6_analytical = coeff * (exp_approx(-ke * 6.0) - exp_approx(-ka * 6.0))
    if c6_analytical > 1.0 {
        let c6_rel = abs_f64(s2.central - c6_analytical) / c6_analytical
        if c6_rel > 0.05 { return 4 }
    }

    // Continue to t=12h
    while j < 1200 {
        s2 = euler_step(s2, dt)
        j = j + 1
    }
    let c12_analytical = coeff * (exp_approx(-ke * 12.0) - exp_approx(-ka * 12.0))
    if c12_analytical > 1.0 {
        let c12_rel = abs_f64(s2.central - c12_analytical) / c12_analytical
        if c12_rel > 0.05 { return 5 }
    }

    return 0
}

//@ run-pass
// One-compartment oral caffeine pharmacokinetic model
// Validates ODE integration with physiological parameters
//
// Model: dA_gut/dt = -ka * A_gut, dA_central/dt = ka * A_gut - ke * A_central
// Parameters: 200 mg oral dose, healthy adult (70 kg)
//   ka = 4.4 /h, CL = 5.46 L/h, V = 42.0 L, ke = CL/V = 0.13 /h, F = 0.99
//
// Rewritten to avoid dynamic arrays and solve_ode builtin
// (lean_single only supports fixed-size arrays)

fn pk_abs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }

fn main() -> i64 with IO, Mut, Div, Panic {
    let ka = 4.4
    let ke = 0.13
    let dose = 200.0
    let F_oral = 0.99
    let V = 42.0
    let dt = 0.01

    // Initial conditions: gut has F*dose mg, central has 0
    var y0 = F_oral * dose   // A_gut
    var y1 = 0.0              // A_central

    // RK4 integration from t=0 to t=24h
    // 2400 steps of dt=0.01h
    // Check values at t=1h (step 100), t=6h (step 600), t=12h (step 1200)
    var Cp_1h = 0.0
    var Cp_6h = 0.0
    var Cp_12h = 0.0

    var step = 0
    while step < 2400 {
        // RK4 for 2D system: f0 = -ka*y0, f1 = ka*y0 - ke*y1
        let k1_0 = 0.0 - ka * y0
        let k1_1 = ka * y0 - ke * y1

        let y0h = y0 + 0.5 * dt * k1_0
        let y1h = y1 + 0.5 * dt * k1_1
        let k2_0 = 0.0 - ka * y0h
        let k2_1 = ka * y0h - ke * y1h

        let y0h2 = y0 + 0.5 * dt * k2_0
        let y1h2 = y1 + 0.5 * dt * k2_1
        let k3_0 = 0.0 - ka * y0h2
        let k3_1 = ka * y0h2 - ke * y1h2

        let y0e = y0 + dt * k3_0
        let y1e = y1 + dt * k3_1
        let k4_0 = 0.0 - ka * y0e
        let k4_1 = ka * y0e - ke * y1e

        y0 = y0 + (dt / 6.0) * (k1_0 + 2.0 * k2_0 + 2.0 * k3_0 + k4_0)
        y1 = y1 + (dt / 6.0) * (k1_1 + 2.0 * k2_1 + 2.0 * k3_1 + k4_1)

        step = step + 1
        if step == 100 { Cp_1h = y1 / V }
        if step == 600 { Cp_6h = y1 / V }
        if step == 1200 { Cp_12h = y1 / V }
    }

    // Validate against analytical Bateman function
    let err_1h = pk_abs(Cp_1h - 4.206)
    let err_6h = pk_abs(Cp_6h - 2.227)
    let err_12h = pk_abs(Cp_12h - 1.021)

    var n_pass = 0
    if err_1h < 0.1 { n_pass = n_pass + 1 }
    if err_6h < 0.1 { n_pass = n_pass + 1 }
    if err_12h < 0.1 { n_pass = n_pass + 1 }

    // Total remaining at 24h should be less than initial dose
    let total_final = y0 + y1
    if total_final < F_oral * dose { n_pass = n_pass + 1 }

    if n_pass == 4 {
        println("PBPK caffeine test passed")
        println("  Cp(1h)  correct (expected ~4.2 mg/L)")
        println("  Cp(6h)  correct (expected ~2.2 mg/L)")
        println("  Cp(12h) correct (expected ~1.0 mg/L)")
        println("  Total remaining at 24h < initial dose")
        return 0
    } else {
        println("PBPK caffeine test FAILED")
        return 1
    }
}

//@ run-pass
// Phase 1 regression: second-order GUM variance closes a >15% gap that
// first-order (delta-method) propagation cannot see.
//
// Rapamycin PBPK — nonlinear regime (simplified):
//
//   R(C, k) = C² · k      // curvature ∂²R/∂C² = 2k is non-zero
//
// With C representing drug concentration and k a rate-like parameter, both
// at ≈ unity with σ² = 0.2 (45% relative SD — typical for batch variability
// in sirolimus pharmacokinetics per Zhang et al. 2018).
//
// Expected (hand-computed):
//   J_C = 2·C·k = 2,  J_k = C² = 1        =>  J = [2, 1, 0, ...]
//   H_CC = 2·k = 2,   H_Ck = 2·C = 2, H_kk = 0
//   σ²_1st(R) = 4·0.2 + 1·0.2 + 0         = 1.00
//   tr(HΣHΣ) = 4·(0.2)² + 8·(0.2)·(0.2)   = 0.48
//   σ²_2nd(R) = 1.00 + 0.5·0.48           = 1.24
//   ratio σ²_2nd/σ²_1st                   = 1.24  (24% first-order underestimate)

// =============================================================================
// Inlined helpers (matches stdlib/epistemic/gum.sio and covariance.sio)
// =============================================================================

struct CovMat {
    n: i32,
    data: [f64; 300],
}

fn tri_idx_cov(n: i32, i: i32, j: i32) -> i32 with Mut {
    var row = i
    var col = j
    if i > j { row = j; col = i }
    return row * n - (row * (row - 1)) / 2 + (col - row)
}

fn cm_new(n: i32) -> CovMat {
    return CovMat { n: n, data: [0.0; 300] }
}

fn cm_set(cov: &!CovMat, i: i32, j: i32, val: f64) with Mut {
    let idx = tri_idx_cov(cov.n, i, j)
    cov.data[idx] = val
}

fn cm_get(cov: &CovMat, i: i32, j: i32) -> f64 with Mut {
    let idx = tri_idx_cov(cov.n, i, j)
    return cov.data[idx]
}

fn hess_tri_idx_8(i: i32, j: i32) -> i32 with Mut {
    var r = i
    var c = j
    if r > c { r = j; c = i }
    return 8 * r - (r * (r - 1)) / 2 + (c - r)
}

fn hess_get_8(h: [f64; 36], i: i32, j: i32) -> f64 with Mut {
    return h[hess_tri_idx_8(i, j)]
}

fn gum_first_order_variance(j: [f64; 8], sigma: &CovMat) -> f64 with Mut {
    var acc: f64 = 0.0
    var i: i32 = 0
    while i < 8 {
        var k: i32 = 0
        while k < 8 {
            acc = acc + j[i] * cm_get(sigma, i, k) * j[k]
            k = k + 1
        }
        i = i + 1
    }
    return acc
}

fn gum_trace_hshs(h: [f64; 36], sigma: &CovMat) -> f64 with Mut {
    var acc: f64 = 0.0
    var i: i32 = 0
    while i < 8 {
        var j: i32 = 0
        while j < 8 {
            let h_ij = hess_get_8(h, i, j)
            var k: i32 = 0
            while k < 8 {
                let s_jk = cm_get(sigma, j, k)
                var l: i32 = 0
                while l < 8 {
                    let h_kl = hess_get_8(h, k, l)
                    let s_li = cm_get(sigma, l, i)
                    acc = acc + h_ij * s_jk * h_kl * s_li
                    l = l + 1
                }
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return acc
}

fn gum_second_order_variance(j: [f64; 8], h: [f64; 36], sigma: &CovMat) -> f64 with Mut, Div {
    let v1 = gum_first_order_variance(j, sigma)
    let trace = gum_trace_hshs(h, sigma)
    return v1 + 0.5 * trace
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

// =============================================================================
// PBPK rapamycin: R(C, k) = C² · k
// =============================================================================

fn rapamycin_nonlinear_ratio() -> f64 with IO, Epistemic, Mut, Div {
    // Drug concentration C (channel 0), rate-like k (channel 1)
    let cm: Knowledge<f64> = measure(1.0, uncertainty: 0.0)
    let km: Knowledge<f64> = measure(1.0, uncertainty: 0.0)
    let c = cm.value
    let k = km.value
    // Nonlinear response — second-order curvature matters here
    let r = c * c * k
    // Collect Jacobian (channels 0..7)
    let jac: [f64; 8] = [sensitivity_of(r, 0), sensitivity_of(r, 1), sensitivity_of(r, 2), sensitivity_of(r, 3), sensitivity_of(r, 4), sensitivity_of(r, 5), sensitivity_of(r, 6), sensitivity_of(r, 7)]
    // Upper-triangular Hessian (36 entries).  Under GTT, r's topology is
    // {0, 1} — only H[0,0], H[0,1], H[1,1] are in-topology and hence the
    // only analytically non-zero entries.  Out-of-topology queries are a
    // type error (see gtt_let_bound_out_of_topology.sio); default-init
    // supplies the mathematical zeros for the other 33 slots.
    var h: [f64; 36] = [0.0; 36]
    h[0] = hessian_of(r, 0, 0)    // H_cc = 2k  = 2.0
    h[1] = hessian_of(r, 0, 1)    // H_ck = 2c  = 2.0
    h[8] = hessian_of(r, 1, 1)    // H_kk = 0.0
    // Covariance: σ²_C = σ²_k = 0.2 (uncorrelated)
    var sigma = cm_new(8)
    cm_set(&!sigma, 0, 0, 0.2)
    cm_set(&!sigma, 1, 1, 0.2)
    // Compute both variances
    let v1 = gum_first_order_variance(jac, &sigma)
    let v2 = gum_second_order_variance(jac, h, &sigma)
    // Return the ratio σ²_2nd / σ²_1st — expected ≈ 1.24 (24% gap)
    return v2 / v1
}

fn main() with IO, Epistemic, Mut, Div {
    let ratio = rapamycin_nonlinear_ratio()
    // Gate: ratio must exceed 1.15 (first-order underestimates by ≥ 15%)
    println(ratio)                    // expect ≈ 1.240000
    if ratio >= 1.15 {
        println(1)                    // 1 = gate passed
    } else {
        println(0)                    // 0 = gate failed
    }
}

//@ run-pass
// PBPK Validation: 2-compartment Euler model vs analytical Bateman equation
//
// Model: Dose → Gut (absorption) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dCentral/dt = ka * Gut - ke * Central
//
// Analytical (Bateman equation):
//   Gut(t)     = Dose * exp(-ka * t)
//   Central(t) = Dose * ka / (ka - ke) * (exp(-ke * t) - exp(-ka * t))
//   AUC(0→∞)   = Dose / ke  (for complete absorption)
//
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.1h, 240 steps (24h)

struct PBPKState {
    t: f64,
    gut: f64,
    central: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn euler_step(s: PBPKState, dt: f64) -> PBPKState with Mut {
    let ka = 1.0
    let ke = 0.1
    let d_gut = -ka * s.gut
    let d_central = ka * s.gut - ke * s.central
    let new_central = s.central + d_central * dt

    // Track Cmax/Tmax
    let new_t = s.t + dt
    var cmax = s.cmax
    var tmax = s.tmax
    if new_central > s.cmax {
        cmax = new_central
        tmax = new_t
    }

    PBPKState {
        t: new_t,
        gut: s.gut + d_gut * dt,
        central: new_central,
        auc: s.auc + s.central * dt,
        cmax: cmax,
        tmax: tmax
    }
}

fn main() -> i32 with IO, Div, Mut {
    var s = PBPKState {
        t: 0.0, gut: 500.0, central: 0.0,
        auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.1
    var i = 0

    while i < 240 {
        s = euler_step(s, dt)
        i = i + 1
    }

    // Print results for validation
    println(s.t)
    println(s.gut)
    println(s.central)
    println(s.auc)
    println(s.cmax)
    println(s.tmax)

    // Validate against analytical expectations:
    //
    // 1. Time should be 24.0h
    if s.t < 23.9 { return 1 }
    if s.t > 24.1 { return 2 }

    // 2. Gut should be ~0 (exp(-24) ≈ 1.9e-11)
    if s.gut > 0.01 { return 3 }

    // 3. Central: Bateman at t=24h
    //    C(24) = 500 * 1.0/(1.0-0.1) * (exp(-0.1*24) - exp(-1.0*24))
    //          = 555.56 * (exp(-2.4) - exp(-24))
    //          = 555.56 * (0.0907 - ~0)
    //          = ~50.4 mg
    //    Euler with dt=0.1 will be close but not exact
    if s.central < 30.0 { return 4 }
    if s.central > 70.0 { return 5 }

    // 4. AUC should be substantial (analytical AUC_0-inf = Dose/ke = 5000)
    //    But we only integrate to 24h, so expect ~4000-5000
    if s.auc < 3000.0 { return 6 }
    if s.auc > 6000.0 { return 7 }

    // 5. Cmax should be ~200-300 mg (depends on ka/ke ratio)
    //    Analytical Cmax at tmax = ln(ka/ke)/(ka-ke) = ln(10)/0.9 ≈ 2.56h
    //    Cmax = 500*(1.0/0.9)*(0.1^(0.1/0.9) - 0.1^(1.0/0.9))
    //    Euler approximation: should be in ballpark
    if s.cmax < 100.0 { return 8 }
    if s.cmax > 400.0 { return 9 }

    // 6. Tmax should be near 2.56h (analytical)
    if s.tmax < 1.5 { return 10 }
    if s.tmax > 4.0 { return 11 }

    return 0
}

//@ run-pass
// PBPK Validation: 3-compartment RK2 model with higher-order accuracy
//
// Model: Gut → Liver (first-pass) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dLiver/dt   = ka * Gut * fa - (Q_h/V_h) * Liver - CL_h * Liver
//   dCentral/dt = (Q_h/V_h) * Liver - ke * Central
//
// Uses RK2 (midpoint method) for 2nd-order accuracy
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.05h, 480 steps (24h)

struct Conc {
    gut: f64,
    liver: f64,
    central: f64
}

struct SimState {
    state: Conc,
    t: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn derivatives(s: Conc) -> Conc {
    let ka = 1.0
    let fa = 0.8
    let q_h = 0.5
    let cl_h = 0.3
    let ke = 0.1
    Conc {
        gut: -ka * s.gut,
        liver: ka * s.gut * fa - q_h * s.liver - cl_h * s.liver,
        central: q_h * s.liver - ke * s.central
    }
}

fn rk2_step(s: Conc, dt: f64) -> Conc {
    // k1 = f(y_n)
    let k1 = derivatives(s)

    // midpoint: y_mid = y_n + 0.5*dt*k1
    let mid = Conc {
        gut: s.gut + 0.5 * dt * k1.gut,
        liver: s.liver + 0.5 * dt * k1.liver,
        central: s.central + 0.5 * dt * k1.central
    }

    // k2 = f(y_mid)
    let k2 = derivatives(mid)

    // y_{n+1} = y_n + dt * k2
    Conc {
        gut: s.gut + dt * k2.gut,
        liver: s.liver + dt * k2.liver,
        central: s.central + dt * k2.central
    }
}

fn main() -> i32 with IO, Div, Mut {
    var sim = SimState {
        state: Conc { gut: 500.0, liver: 0.0, central: 0.0 },
        t: 0.0, auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.05
    var i = 0

    while i < 480 {
        let new_state = rk2_step(sim.state, dt)
        let new_t = sim.t + dt

        // Trapezoidal AUC
        let auc_increment = 0.5 * (sim.state.central + new_state.central) * dt

        var cmax = sim.cmax
        var tmax = sim.tmax
        if new_state.central > sim.cmax {
            cmax = new_state.central
            tmax = new_t
        }

        sim = SimState {
            state: new_state,
            t: new_t,
            auc: sim.auc + auc_increment,
            cmax: cmax,
            tmax: tmax
        }
        i = i + 1
    }

    // Print results
    println(sim.t)
    println(sim.state.gut)
    println(sim.state.liver)
    println(sim.state.central)
    println(sim.auc)
    println(sim.cmax)
    println(sim.tmax)

    // Validate:
    // 1. Time = 24.0h
    if sim.t < 23.9 { return 1 }

    // 2. Gut fully absorbed (exp(-24) ≈ 0)
    if sim.state.gut > 0.01 { return 2 }

    // 3. AUC should be positive and substantial
    if sim.auc < 100.0 { return 3 }

    // 4. Cmax > 0 (drug reached central compartment)
    if sim.cmax < 10.0 { return 4 }

    // 5. Tmax in physiological range (1-8h for oral absorption)
    if sim.tmax < 0.5 { return 5 }
    if sim.tmax > 12.0 { return 6 }

    // 6. All concentrations non-negative (conservation of mass)
    if sim.state.gut < 0.0 { return 7 }
    if sim.state.liver < 0.0 { return 8 }
    if sim.state.central < 0.0 { return 9 }

    // 7. 480 iterations completed
    if i != 480 { return 10 }

    return 0
}

//@ run-pass
//@ expect-stdout: ALL PASS
//
// L0 acceptance for the perturbation DAG (stdlib/epistemic/perturbation_graph.sio):
// binary chaining of uncertain octonion products is ORDER-SAFE — the structural
// (non-associativity) variance is accumulated automatically regardless of how the
// product is parenthesized, so ((a·b)·c) and (a·(b·c)) agree, and both match the
// explicit mul3.
//
// Operands: unit basis octonions (norm²=1), σ=0.5 (var=0.25), κ=1.
//   non-Fano (e1,e2,e4): measurement 0.75 + κ·‖α‖²(=4) = 4.75 (either association)
//   Fano     (e1,e2,e3): measurement 0.75 + 0              = 0.75
// The order-naive value-only binary would drop the structural term → 0.75 (wrong).

use epistemic::perturbation_graph::{PerturbGraph, pg_new, pg_leaf, pg_mul, pg_variance}
use algebra::octonion::oct_basis

fn approx(x: f64, y: f64) -> bool {
    let d = if x > y { x - y } else { y - x }
    d < 0.0001
}

fn main() with Mut, Div, Panic, NonAssoc {
    var ok = true
    let e1 = oct_basis(1)
    let e2 = oct_basis(2)
    let e3 = oct_basis(3)
    let e4 = oct_basis(4)

    // non-Fano, LEFT-associated: (a·b)·c
    var g = pg_new()
    let a  = pg_leaf(&!g, &e1, 0.5)
    let b  = pg_leaf(&!g, &e2, 0.5)
    let c  = pg_leaf(&!g, &e4, 0.5)
    let ab  = pg_mul(&!g, a, b, 1.0)
    let abc = pg_mul(&!g, ab, c, 1.0)
    let v_left = pg_variance(&!g, abc)
    if approx(v_left, 4.75) { print("LEFT (ab)c = 4.75: PASS") }
    else { print("LEFT: FAIL"); ok = false }

    // non-Fano, RIGHT-associated: a·(b·c) — must match
    var g2 = pg_new()
    let a2 = pg_leaf(&!g2, &e1, 0.5)
    let b2 = pg_leaf(&!g2, &e2, 0.5)
    let c2 = pg_leaf(&!g2, &e4, 0.5)
    let bc   = pg_mul(&!g2, b2, c2, 1.0)
    let abc2 = pg_mul(&!g2, a2, bc, 1.0)
    let v_right = pg_variance(&!g2, abc2)
    if approx(v_right, 4.75) { print("RIGHT a(bc) = 4.75: PASS") }
    else { print("RIGHT: FAIL"); ok = false }

    if approx(v_left, v_right) { print("order-safe: left == right: PASS") }
    else { print("order-safe: FAIL"); ok = false }

    // Fano triple pays nothing
    var g3 = pg_new()
    let fa = pg_leaf(&!g3, &e1, 0.5)
    let fb = pg_leaf(&!g3, &e2, 0.5)
    let fc = pg_leaf(&!g3, &e3, 0.5)
    let fab  = pg_mul(&!g3, fa, fb, 1.0)
    let fabc = pg_mul(&!g3, fab, fc, 1.0)
    if approx(pg_variance(&!g3, fabc), 0.75) { print("Fano chain = 0.75: PASS") }
    else { print("Fano: FAIL"); ok = false }

    if ok { print("ALL PASS") } else { print("SOME FAIL") }
}

//@ run-pass
// PK Domain Uncertainty Plugin Test Suite
//
// Validates WS2 Track 5 — PK-specific uncertainty analysis:
//   1.  Clearance dominance detection (CL contributes >70%)
//   2.  Volume dominance detection (V contributes most)
//   3.  Balanced contributions (no single dominant)
//   4.  SCr as proxy for clearance (Cockcroft-Gault scenario)
//   5.  Sensitivity index S_Ti > 0.7 triggers clearance dominance flag
//   6.  PK recommendations: clearance dominant -> TDM
//   7.  PK recommendations: absorption dominant -> bioequivalence
//   8.  Clinical significance: uncertainty > therapeutic window
//   9.  Clinical significance: uncertainty < therapeutic window
//  10.  Edge case: single parameter is 100% dominant
//  11.  Recommendation for SCr dominant -> cystatin C
//  12.  Sensitivity indices sum to 1.0
//
// Reference: Saltelli et al. (2008), FDA PopPK Guidance (2022)

// ============================================================================
// HELPERS
// ============================================================================

fn abs_val(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn sqrt_val(x: f64) -> f64 with Mut, Div {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    if guess < 0.001 { guess = 0.001 }
    var i = 0
    while i < 30 {
        guess = (guess + x / guess) / 2.0
        i = i + 1
    }
    return guess
}

// ============================================================================
// FLAT PKProfile STRUCT
// No nested structs — all parameter data in flat arrays.
// ============================================================================

struct PKProfile {
    n_params: i64,
    p_code: [i64; 8],
    p_value: [f64; 8],
    p_std_uncert: [f64; 8],
    p_sensitivity: [f64; 8],
    p_contribution: [f64; 8],
    p_source_type: [i64; 8],
    combined_variance: f64,
    combined_std_uncert: f64,
    clearance_contribution: f64,
    volume_contribution: f64,
    absorption_contribution: f64,
    is_cl_dominant: i64,
    dominant_idx: i64,
    dominant_pct: f64,
    r0: i64,
    r1: i64,
    r2: i64,
    r3: i64,
    n_rec: i64
}

fn empty_profile() -> PKProfile {
    PKProfile {
        n_params: 0,
        p_code: [0; 8],
        p_value: [0.0; 8],
        p_std_uncert: [0.0; 8],
        p_sensitivity: [0.0; 8],
        p_contribution: [0.0; 8],
        p_source_type: [0; 8],
        combined_variance: 0.0,
        combined_std_uncert: 0.0,
        clearance_contribution: 0.0,
        volume_contribution: 0.0,
        absorption_contribution: 0.0,
        is_cl_dominant: 0,
        dominant_idx: 0,
        dominant_pct: 0.0,
        r0: 0, r1: 0, r2: 0, r3: 0,
        n_rec: 0
    }
}

fn set_param(profile: PKProfile, idx: i64, code: i64, value: f64, std_uncert: f64, sensitivity: f64, source_type: i64) -> PKProfile with Mut {
    var r = profile
    let contrib = sensitivity * sensitivity * std_uncert * std_uncert
    r.p_code[idx as usize] = code
    r.p_value[idx as usize] = value
    r.p_std_uncert[idx as usize] = std_uncert
    r.p_sensitivity[idx as usize] = sensitivity
    r.p_contribution[idx as usize] = contrib
    r.p_source_type[idx as usize] = source_type
    return r
}

// ============================================================================
// FLAT PKSens STRUCT
// ============================================================================

struct PKSens {
    s_ti: [f64; 8],
    s_i: [f64; 8],
    n_params: i64,
    dom_idx: i64,
    dom_s_ti: f64,
    cl_dominant: i64
}

fn empty_sens() -> PKSens {
    PKSens {
        s_ti: [0.0; 8],
        s_i: [0.0; 8],
        n_params: 0,
        dom_idx: 0,
        dom_s_ti: 0.0,
        cl_dominant: 0
    }
}

// ============================================================================
// PARAMETER CLASSIFICATION
// ============================================================================

fn is_cl(code: i64) -> bool {
    if code == 0 { return true }
    if code == 3 { return true }
    if code == 7 { return true }
    if code == 6 { return true }
    return false
}

fn is_vol(code: i64) -> bool {
    if code == 1 { return true }
    if code == 6 { return true }
    return false
}

fn is_abs(code: i64) -> bool {
    if code == 2 { return true }
    if code == 4 { return true }
    return false
}

// ============================================================================
// ANALYSIS FUNCTIONS
// ============================================================================

fn compute_contributions(profile: PKProfile, n: i64) -> PKProfile with Mut, Div {
    var r = profile
    r.n_params = n

    var total: f64 = 0.0
    var i = 0
    while i < n {
        total = total + r.p_contribution[i as usize]
        i = i + 1
    }

    r.combined_variance = total
    r.combined_std_uncert = sqrt_val(total)

    if total < 1.0e-15 {
        return r
    }

    var cl: f64 = 0.0
    var v: f64 = 0.0
    var ab: f64 = 0.0
    var best_idx = 0
    var best_pct: f64 = 0.0

    i = 0
    while i < n {
        let contrib = r.p_contribution[i as usize]
        let code = r.p_code[i as usize]
        let pct = 100.0 * contrib / total

        if pct > best_pct {
            best_pct = pct
            best_idx = i
        }
        if is_cl(code) { cl = cl + pct }
        if is_vol(code) { v = v + pct }
        if is_abs(code) { ab = ab + pct }

        i = i + 1
    }

    r.clearance_contribution = cl
    r.volume_contribution = v
    r.absorption_contribution = ab
    r.dominant_idx = best_idx
    r.dominant_pct = best_pct

    if cl > 70.0 {
        r.is_cl_dominant = 1
    } else {
        r.is_cl_dominant = 0
    }

    return r
}

fn compute_sensitivity(profile: PKProfile, n: i64) -> PKSens with Mut, Div {
    var r = empty_sens()
    r.n_params = n

    var total: f64 = 0.0
    var i = 0
    while i < n {
        total = total + profile.p_contribution[i as usize]
        i = i + 1
    }

    if total < 1.0e-15 {
        return r
    }

    var best_idx = 0
    var best_s_ti: f64 = 0.0

    i = 0
    while i < n {
        let s_ti = profile.p_contribution[i as usize] / total
        r.s_ti[i as usize] = s_ti
        r.s_i[i as usize] = s_ti
        if s_ti > best_s_ti {
            best_s_ti = s_ti
            best_idx = i
        }
        i = i + 1
    }

    r.dom_idx = best_idx
    r.dom_s_ti = best_s_ti

    var cl_total: f64 = 0.0
    i = 0
    while i < n {
        if is_cl(profile.p_code[i as usize]) {
            cl_total = cl_total + profile.p_contribution[i as usize] / total
        }
        i = i + 1
    }

    if cl_total > 0.7 {
        r.cl_dominant = 1
    } else {
        r.cl_dominant = 0
    }

    return r
}

fn generate_rec(profile: PKProfile) -> PKProfile with Mut, Div {
    var r = profile
    var n_rec = 0

    if profile.is_cl_dominant != 0 {
        if n_rec == 0 { r.r0 = 10 }
        else if n_rec == 1 { r.r1 = 10 }
        else if n_rec == 2 { r.r2 = 10 }
        else if n_rec == 3 { r.r3 = 10 }
        n_rec = n_rec + 1
    }

    if profile.volume_contribution > 50.0 {
        if n_rec == 0 { r.r0 = 11 }
        else if n_rec == 1 { r.r1 = 11 }
        else if n_rec == 2 { r.r2 = 11 }
        else if n_rec == 3 { r.r3 = 11 }
        n_rec = n_rec + 1
    }

    if profile.absorption_contribution > 50.0 {
        if n_rec == 0 { r.r0 = 12 }
        else if n_rec == 1 { r.r1 = 12 }
        else if n_rec == 2 { r.r2 = 12 }
        else if n_rec == 3 { r.r3 = 12 }
        n_rec = n_rec + 1
    }

    if profile.is_cl_dominant != 0 {
        var scr_pct: f64 = 0.0
        var i = 0
        while i < profile.n_params {
            if profile.p_code[i as usize] == 7 {
                if profile.combined_variance > 1.0e-15 {
                    scr_pct = 100.0 * profile.p_contribution[i as usize] / profile.combined_variance
                }
            }
            i = i + 1
        }
        if scr_pct > 20.0 {
            if n_rec < 4 {
                if n_rec == 0 { r.r0 = 13 }
                else if n_rec == 1 { r.r1 = 13 }
                else if n_rec == 2 { r.r2 = 13 }
                else if n_rec == 3 { r.r3 = 13 }
                n_rec = n_rec + 1
            }
        }
    }

    if profile.combined_std_uncert > 0.0 {
        let dom_val = profile.p_value[profile.dominant_idx as usize]
        if abs_val(dom_val) > 1.0e-15 {
            let rel_uncert = 100.0 * profile.combined_std_uncert / abs_val(dom_val)
            if rel_uncert > 30.0 {
                if n_rec < 4 {
                    if n_rec == 0 { r.r0 = 14 }
                    else if n_rec == 1 { r.r1 = 14 }
                    else if n_rec == 2 { r.r2 = 14 }
                    else if n_rec == 3 { r.r3 = 14 }
                    n_rec = n_rec + 1
                }
            }
        }
    }

    if n_rec > 4 { r.n_rec = 4 } else { r.n_rec = n_rec }
    return r
}

fn pk_analyze(profile: PKProfile, n: i64) -> PKProfile with Mut, Div {
    var r = compute_contributions(profile, n)
    r = generate_rec(r)
    return r
}

fn is_clinically_sig(profile: PKProfile, tw: f64) -> i64 with Div {
    if tw <= 1.0 { return 1 }
    let half_width = 2.0 * profile.combined_std_uncert
    let dom_val = profile.p_value[profile.dominant_idx as usize]
    if abs_val(dom_val) < 1.0e-15 { return 1 }
    let rel_half = half_width / abs_val(dom_val)
    let margin = 1.0 - 1.0 / tw
    if rel_half > margin { return 1 }
    return 0
}

