    while i < 20 {
        y = (y + x / y) * 0.5
        i = i + 1
    }
    return y
}

fn ep_max(a: f64, b: f64) -> f64 {
    if a > b { return a }
    return b
}

fn ep_min(a: f64, b: f64) -> f64 {
    if a < b { return a }
    return b
}

fn cube_root(x: f64) -> f64 with Mut, Div {
    if x <= 0.0 { return 0.0 }
