fn make_test_matrix(rows: i64, cols: i64) -> MatrixData with Mut, Panic {
    var m = matrix_data_new(rows, cols)
    var r: i64 = 0
    while r < rows {
        var c: i64 = 0
        while c < cols {
            let val = ((r + 1) * 10 + (c + 1)) as f64
            m = matrix_data_set(m, r, c, val)
            c = c + 1
        }
        r = r + 1
    }
    m
}

