        25.0, 26.0, 27.0, 28.0, 29.0, 30.0, 31.0, 32.0
    ]

    if slice_len(&arr8) != 8 { return 1 }
    if slice_len(&arr32) != 32 { return 2 }
    if sum(&arr8) != 36.0 { return 3 }
    if sum(&arr32) != 528.0 { return 4 }

    let mid = &arr32[8..16]
    if slice_len(mid) != 8 { return 5 }
    if mid.len() != 8 { return 6 }
    if sum(mid) != 100.0 { return 7 }

    let inner = &mid[2..5]
    if inner.len() != 3 { return 8 }
    if sum(inner) != 36.0 { return 9 }

    var buf = [10.0, 20.0, 30.0, 40.0]
    let tail = &!buf[1..4]
    if slice_len(tail) != 3 { return 10 }
    swap(tail, 0, 2)
    if buf[0] != 10.0 { return 11 }
    if buf[1] != 40.0 { return 12 }
    if buf[2] != 30.0 { return 13 }
    if buf[3] != 20.0 { return 14 }

    return 0
}

