    obj_val: f64,
    constraint_viol: f64,
    iterations: i32,
    converged: bool,
    n_dim: i32
}

struct LBFGSState {
    s_store: [f64; 4096],
    y_store: [f64; 4096],
    rho_store: [f64; 64],
    m: i32,
    n: i32,
    count: i32
}

