    // Triangle: (0,0), (4,0), (1,3)
    // Interior point: (1.5, 1.0)
    var N: [f64; 3] = [0.0; 3]
    fem_tri_shape(0.0, 0.0, 4.0, 0.0, 1.0, 3.0, 1.5, 1.0, &!N)

